package cn.huankan.event;
import java.util.*;import java.time.Instant;import cn.huankan.evidence.EvidenceService;import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ImpactService {
 private final JdbcTemplate db;private final ObjectMapper json;public ImpactService(JdbcTemplate db,ObjectMapper json){this.db=db;this.json=json;}
 public static String rule(String type,String indicator,String title){String t=title.toLowerCase(Locale.ROOT);if(indicator.startsWith("RELATION:"))return "RELATION_CHANGE";if(indicator.startsWith("FM.")||t.contains("interest rate")||t.contains("policy rate")||t.contains("利率"))return "POLICY";if(indicator.startsWith("EXR."))return "REFERENCE_FX";if(t.contains("inflation")||t.contains("consumer price")||t.contains("cpi")||t.contains("居民消费价格"))return "INFLATION";if(type.equals("FINANCIAL_DISCLOSURE"))return "DISCLOSURE";if(t.contains("capital expenditure")||t.contains("capex")||t.contains("资本开支"))return "CAPEX";if(type.equals("LEGAL_IDENTITY_ATTRIBUTE"))return "IDENTITY";return "PUBLICATION";}
 private String encode(Object x){try{return json.writeValueAsString(x);}catch(Exception e){throw new IllegalArgumentException("研判字段编码失败");}}
 @Transactional public Object analyze(UUID fact,Instant asOf){if(fact==null||asOf==null||asOf.isAfter(Instant.now().plusSeconds(5)))throw new IllegalArgumentException("事实与证据截止时刻无效");var f=db.queryForMap("SELECT f.*,f.verification_status effective_status,p.evidence_id,p.excerpt,r.raw_content,r.raw_content_hash,r.source_url,r.collected_at,r.published_at FROM fact_candidate f JOIN fact_evidence p ON p.fact_id=f.id JOIN raw_evidence r ON r.id=p.evidence_id JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=s.id WHERE s.level='L0' AND l.status='APPROVED' AND l.storage_allowed AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND f.id=? AND f.created_at<=? AND r.collected_at<=? AND (r.published_at IS NULL OR r.published_at<=?)",fact,java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf));var reviews=db.queryForList("SELECT decision FROM fact_review WHERE fact_id=? AND created_at<=? ORDER BY created_at DESC,id DESC LIMIT 1",fact,java.sql.Timestamp.from(asOf));if(!reviews.isEmpty())f.put("effective_status",reviews.getFirst().get("decision"));if(!Set.of("SOURCE_CHECKED","FIELD_MATCHED","INDEPENDENT_SUPPORTED").contains(f.get("effective_status")))throw new IllegalArgumentException("事实证据不足，不能生成规则研判");if(!EvidenceService.hash((byte[])f.get("raw_content")).equals(f.get("raw_content_hash")))throw new IllegalArgumentException("研判证据哈希异常");
  Map<String,Object> fields;try{fields=json.readValue(f.get("fields").toString(),new com.fasterxml.jackson.core.type.TypeReference<>(){});}catch(Exception e){throw new IllegalArgumentException("原子事实字段异常");}String rule=rule(f.get("fact_type").toString(),Objects.toString(fields.get("indicator_id"),""),Objects.toString(fields.get("original_title"),""));String mechanism=switch(rule){case "POLICY"->"政策利率可能通过融资成本、现金流折现与银行息差传导；当前没有市场预期、相邻有效值与企业敞口证据，不能判断意外程度与方向";case "REFERENCE_FX"->"参考汇率可能改变外币收入与进口成本折算；必须结合币种方向、合同和实际敞口，参考汇率不是成交行情";case "INFLATION"->"物价变化可能经实际购买力、政策预期与企业成本传导；尚无同比环比、预期差或产业成本分项的充分证据";case "DISCLOSURE"->"披露可能改变现金流与盈利预期；会计口径、比较期间和指引可信度需另行核验";case "CAPEX"->"资本开支可能形成未来产能与需求，同时占用现金流；金额、执行期、融资来源与真实供应关系需核验";case "RELATION_CHANGE"->"已审核关系变化可能改变需求、成本、竞争格局或会计并表范围；只有确切披露和有效期间内的真实关系可用于研判，名称共现与未审候选不能作为输入";case "IDENTITY"->"法人登记变化仅反映身份主数据，不能推断营业表现、证券收益或供应链变化";default->"目前仅确认官方发布。标题关键词不能替代正文事实与已核实业务关系";};
  var report=new LinkedHashMap<String,Object>();report.put("summary",Objects.toString(fields.get("original_title"),Objects.toString(fields.get("indicator_id"),"官方事实规则研判")));report.put("source",Map.of("url",f.get("source_url"),"evidence_id",f.get("evidence_id"),"as_of",asOf.toString()));report.put("integrity",Map.of("sha256",f.get("raw_content_hash"),"result","本次实际字节哈希通过"));report.put("event_id",f.get("event_id"));report.put("fact_id",fact);report.put("fact_status",f.get("effective_status"));report.put("knowledge_kind","规则影响假设；事实和市场结果分别核验");report.put("facts",fields);var entities=db.queryForList("SELECT e.id,e.type,e.official_name,ee.evidence_id,ee.match_basis FROM event_entity ee JOIN financial_entity e ON e.id=ee.entity_id JOIN raw_evidence r ON r.id=ee.evidence_id WHERE ee.event_id=? AND ee.status='VERIFIED' AND e.status='VERIFIED' AND r.collected_at<=? AND r.raw_content_hash=encode(sha256(r.raw_content),'hex')",f.get("event_id"),java.sql.Timestamp.from(asOf));
  var relations=db.queryForList("SELECT er.id,er.type,er.relation_kind,er.subject_id,er.object_id,er.evidence_id,r.raw_content_hash,r.source_url,er.explanation FROM entity_relation er JOIN raw_evidence r ON r.id=er.evidence_id JOIN source_license l ON l.source_id=r.source_id WHERE er.status='VERIFIED' AND er.relation_kind IN('BUSINESS_FACT','INDUSTRY_MEMBERSHIP','ACCOUNTING_CONSOLIDATION','LEGAL_IDENTITY') AND l.status='APPROVED' AND l.display_allowed AND (l.valid_until IS NULL OR l.valid_until>now()) AND r.collected_at<=? AND er.disclosed_at<=? AND (er.effective_from IS NULL OR er.effective_from<=?) AND (er.effective_until IS NULL OR er.effective_until>?) AND EXISTS(SELECT 1 FROM relation_review_history h WHERE h.relation_id=er.id AND h.decision='ACCEPT' AND h.created_at<=?) AND r.raw_content_hash=encode(sha256(r.raw_content),'hex') AND EXISTS(SELECT 1 FROM event_entity ee WHERE ee.event_id=? AND ee.status='VERIFIED' AND (ee.entity_id=er.subject_id OR ee.entity_id=er.object_id))",java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),java.sql.Timestamp.from(asOf),f.get("event_id"));
  report.put("entities",entities);report.put("verified_relations",relations);report.put("relationship_boundary","法人、并表、行业、供应关系分开；会计并表不证明供应链，宏观敏感性仍是待验证假设");report.put("industry",List.of());report.put("mechanism",mechanism);report.put("positive",List.of("条件性假设：只有成本下降、需求改善或可验证现金流增加时，相关敞口主体才可能受益；尚无主体证据"));report.put("negative",List.of("条件性假设：成本上升、购买力下降或现金流压力扩大时，相关敞口主体可能承压；尚无主体证据"));report.put("counter_evidence",List.of("当前未取得独立反向证据；缺少反向证据不代表假设已成立"));report.put("gaps",List.of("市场预期与价格收益未验证","真实企业敞口及业务关系证据不足","官方公布字段不能证明全部经济解释"));report.put("watch_variables",List.of("后续官方修订","相邻同口径观测","企业正式披露","真实市场数据接入后的事件窗口"));report.put("validity",List.of("仅适用于本次证据截止快照","单位、口径或原始值被修订时需新建结果","新增反向证据可能使假设失效"));report.put("market_status","待验证，没有生成行情、收益率或交易建议");var conditions=Map.of("fact_status",f.get("effective_status"),"source_acquired_before_cutoff",true,"qualified_relations",relations.size(),"missing_entities_not_inferred",true);UUID id=UUID.randomUUID();db.update("INSERT INTO impact_assessment(id,fact_id,rule_id,rule_version,as_of,input_evidence_id,input_hash,conditions,report) VALUES(?,?,?,'规则研判-1.1',?,?,?,?::jsonb,?::jsonb) ON CONFLICT DO NOTHING",id,fact,rule,java.sql.Timestamp.from(asOf),f.get("evidence_id"),f.get("raw_content_hash"),encode(conditions),encode(report));return view(db.queryForMap("SELECT * FROM impact_assessment WHERE fact_id=? AND rule_id=? AND rule_version='规则研判-1.1' AND as_of=?",fact,rule,java.sql.Timestamp.from(asOf)));}
 public Object query(int page){if(page<0||page>100000)throw new IllegalArgumentException("研判分页无效");var rows=db.queryForList("SELECT * FROM impact_assessment ORDER BY created_at DESC,id LIMIT 50 OFFSET ?",page*50);rows.forEach(this::view);return rows;}
 private Map<String,Object> view(Map<String,Object> row){try{for(String field:List.of("report","conditions"))row.put(field,json.readValue(row.get(field).toString(),Map.class));return row;}catch(Exception e){throw new IllegalArgumentException("研判结构化字段无法读取");}}
}
